Get an access token:

```typescript
// Obtain an access token for authenticating with the QWeather API.
async function getToken(apiKey: string, grantType: string) {
  try {
    const tokenResponse = await client.post_v2_rest_token({ key: apiKey, grant_type: grantType });
    if (tokenResponse.code === "200") {
      return tokenResponse.access_token;
    } else {
      console.error("Failed to obtain token:", tokenResponse.msg);
      return null;
    }
  } catch (error) {
    console.error("Error obtaining token:", error);
    return null;
  }
}
```

Get the current weather:

```typescript
